import { useEffect, useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import api from '../api/axiosConfig';
import '../styles/animations.css';

const COULEURS_STATUT = {
  'en attente': { bg: '#FFF6E0', texte: '#9A7B14' },
  'acceptée': { bg: '#E3F2E6', texte: '#2E7D32' },
  'refusée': { bg: '#FBEAE7', texte: '#A13D2B' },
};

export default function Dashboard() {
  const { utilisateur, deconnecter } = useAuth();
  const navigate = useNavigate();
  const [statutServeur, setStatutServeur] = useState(null);
  const [profilDetaille, setProfilDetaille] = useState(null);
  const [mesDemandes, setMesDemandes] = useState([]);
  const [erreur, setErreur] = useState('');

  useEffect(() => {
    if (!utilisateur) {
      navigate('/connexion');
      return;
    }

    const chargerDonnees = async () => {
      try {
        const [resStatut, resProfil, resDemandes] = await Promise.all([
          api.get('/serveur/statut'),
          api.get('/auth/profil'),
          api.get('/demandes/mes-demandes')
        ]);
        setStatutServeur(resStatut.data);
        setProfilDetaille(resProfil.data.utilisateur);
        setMesDemandes(resDemandes.data.demandes);
      } catch (err) {
        setErreur('Impossible de joindre le serveur ou session expirée.');
      }
    };
    chargerDonnees();
  }, [utilisateur, navigate]);

  const gererDeconnexion = () => {
    deconnecter();
    navigate('/connexion');
  };

  if (!utilisateur) return null;

  return (
    <div className="tableau-bord">
      <div className="tb-entete">
        <div>
          <div className="dossier-eyebrow" style={{ color: 'var(--sceau)' }}>Espace citoyen</div>
          <h2 style={{ margin: '4px 0 0', fontFamily: "'Fraunces', serif" }}>
            Bonjour, {utilisateur.prenom} {utilisateur.nom}
          </h2>
        </div>
        <div style={{ display: 'flex', gap: 10 }}>
          <Link to="/nouvelle-demande" className="bouton-tamponner" style={{ padding: '10px 18px', fontSize: 13, textDecoration: 'none', display: 'inline-block' }}>
            Nouvelle demande
          </Link>
          <button onClick={gererDeconnexion} className="bouton-tamponner" style={{ padding: '10px 18px', fontSize: 13, background: 'var(--ardoise)' }}>
            Se déconnecter
          </button>
        </div>
      </div>

      <div className="tb-carte">
        {erreur && <div className="message-erreur">{erreur}</div>}

        <div className="statut-serveur">
          <span className="point-vert" />
          {statutServeur ? statutServeur.message : 'Vérification de la connexion au serveur…'}
        </div>

        <h3 style={{ fontFamily: "'Fraunces', serif", marginBottom: 4 }}>Vos informations</h3>

        {profilDetaille && (
          <div className="grille-infos">
            <div className="info-item"><span>Nom</span><strong>{profilDetaille.nom}</strong></div>
            <div className="info-item"><span>Prénom</span><strong>{profilDetaille.prenom}</strong></div>
            <div className="info-item"><span>Email</span><strong>{profilDetaille.email}</strong></div>
            <div className="info-item"><span>Adresse</span><strong>{profilDetaille.adresse || '—'}</strong></div>
            <div className="info-item"><span>Contact</span><strong>{profilDetaille.contact || '—'}</strong></div>
            <div className="info-item"><span>Relation</span><strong>{profilDetaille.relation || '—'}</strong></div>
          </div>
        )}

        <h3 style={{ fontFamily: "'Fraunces', serif", marginTop: 28, marginBottom: 4 }}>Mes demandes</h3>
        {mesDemandes.length === 0 ? (
          <p style={{ color: 'var(--ardoise)', fontSize: 13.5 }}>Aucune demande soumise pour le moment.</p>
        ) : (
          <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 14, marginTop: 12 }}>
            <thead>
              <tr style={{ textAlign: 'left', borderBottom: '2px solid #EFE8D8' }}>
                <th style={{ padding: '8px' }}>N°</th>
                <th style={{ padding: '8px' }}>Type d'acte</th>
                <th style={{ padding: '8px' }}>Prix</th>
                <th style={{ padding: '8px' }}>Statut</th>
              </tr>
            </thead>
            <tbody>
              {mesDemandes.map((d) => {
                const couleurs = COULEURS_STATUT[d.statut] || COULEURS_STATUT['en attente'];
                return (
                  <tr key={d.id_demande} style={{ borderBottom: '1px solid #F1EBDD' }}>
                    <td style={{ padding: '8px' }}>{d.id_demande}</td>
                    <td style={{ padding: '8px' }}>{d.type_acte?.nom || '—'}</td>
                    <td style={{ padding: '8px' }}>{Number(d.prix).toLocaleString('fr-FR')} Ar</td>
                    <td style={{ padding: '8px' }}>
                      <span style={{
                        padding: '3px 10px', borderRadius: 20, fontSize: 12, fontWeight: 600,
                        background: couleurs.bg, color: couleurs.texte
                      }}>
                        {d.statut}
                      </span>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}