import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../api/axiosConfig';
import '../styles/animations.css';

export default function NouvelleDemande() {
  const [typesActes, setTypesActes] = useState([]);
  const [idTypeSelectionne, setIdTypeSelectionne] = useState('');
  const [chargementTypes, setChargementTypes] = useState(true);
  const [chargement, setChargement] = useState(false);
  const [erreur, setErreur] = useState('');
  const [succesMessage, setSuccesMessage] = useState('');
  const navigate = useNavigate();

  useEffect(() => {
    chargerTypesActes();
  }, []);

  const chargerTypesActes = async () => {
    try {
      const { data } = await api.get('/types-actes');
      setTypesActes(data.types);
    } catch (err) {
      setErreur("Impossible de charger la liste des types d'actes.");
    } finally {
      setChargementTypes(false);
    }
  };

  const gererSoumission = async (e) => {
    e.preventDefault();
    setErreur('');
    setChargement(true);
    try {
      const { data } = await api.post('/demandes', { id_types_actes: idTypeSelectionne });
      setSuccesMessage(`Demande envoyée avec succès ! (N° ${data.demande.id_demande})`);
      setTimeout(() => navigate('/tableau-de-bord'), 1800);
    } catch (err) {
      setErreur(err.response?.data?.message || "Erreur lors de l'envoi de la demande.");
    } finally {
      setChargement(false);
    }
  };

  return (
    <div className="page-auth">
      <div className="dossier" style={{ maxWidth: 560 }}>
        <div className="dossier-formulaire" style={{ flex: 1 }}>
          <div className="dossier-eyebrow" style={{ color: 'var(--sceau)' }}>Nouvelle démarche</div>
          <h2 style={{ fontFamily: "'Fraunces', serif", margin: '8px 0 20px' }}>Soumettre une demande</h2>

          {erreur && <div className="message-erreur">{erreur}</div>}
          {succesMessage && (
            <div className="message-erreur" style={{ background: '#E3F2E6', borderColor: '#BEE0C4', color: '#2E7D32' }}>
              {succesMessage}
            </div>
          )}

          {chargementTypes ? (
            <p style={{ color: 'var(--ardoise)', fontSize: 13.5 }}>Chargement des types d'actes disponibles…</p>
          ) : (
            <form onSubmit={gererSoumission}>
              <div className="champ">
                <label>Type d'acte</label>
                <select
                  value={idTypeSelectionne}
                  onChange={(e) => setIdTypeSelectionne(e.target.value)}
                  required
                >
                  <option value="">Sélectionner…</option>
                  {typesActes.map((t) => (
                    <option key={t['id_types-actes']} value={t['id_types-actes']}>
                      {t.nom}
                    </option>
                  ))}
                </select>
              </div>

              {idTypeSelectionne && (
                <div className="champ" style={{ fontSize: 13, color: 'var(--ardoise)' }}>
                  {typesActes.find((t) => t['id_types-actes'] == idTypeSelectionne)?.description}
                </div>
              )}

              <button type="submit" className={`bouton-tamponner ${chargement ? 'en-chargement' : ''}`} disabled={chargement}>
                {chargement ? 'Envoi en cours…' : 'Envoyer la demande'}
              </button>
            </form>
          )}
        </div>
      </div>
    </div>
  );
}